// Nodo 1: Validación y sanitización del resultado de supervivencia
const item = $input.first().json.body || $input.first().json;

const playerId = item.playerId ? String(item.playerId).trim() : 'usr-anon';
const playerName = item.playerName ? String(item.playerName).trim() : 'Entrenador Anónimo';
const difficulty = item.difficulty ? String(item.difficulty).toLowerCase() : 'principiante';
const generation = Number(item.generation) || 1;
const score = Number(item.score) || 0;
const questionsAnswered = Number(item.questionsAnswered) || 0;
const correctAnswers = Number(item.correctAnswers) || 0;
const incorrectAnswers = Number(item.incorrectAnswers) || 0;
const bestStreak = Number(item.bestStreak) || 0;
const hintsUsed = Number(item.hintsUsed) || 0;
const isNewRecord = Boolean(item.isNewRecord);

const isValid = Boolean(item && typeof score === 'number');

return [{
  json: {
    isValid,
    playerId,
    playerName,
    difficulty,
    generation,
    score,
    questionsAnswered,
    correctAnswers,
    incorrectAnswers,
    bestStreak,
    hintsUsed,
    isNewRecord,
    receivedAt: new Date().toISOString()
  }
}];

// Nodo 2: Cálculo de rango, medalla de supervivencia y honores de la Liga
const data = $input.first().json;
const totalQ = data.questionsAnswered || (data.correctAnswers + data.incorrectAnswers) || 1;
const accuracy = Math.round((data.correctAnswers / totalQ) * 100);

let badge = 'Medalla de Supervivencia Principiante';
let rank = 'Entrenador Promesa';

if (data.isNewRecord || data.score >= 600) {
  badge = 'Medalla Campeón Supremo de la Liga';
  rank = 'Maestro de la Supervivencia Pokémon';
} else if (data.score >= 350) {
  badge = 'Medalla Gimnasio Élite';
  rank = 'Líder de Supervivencia';
} else {
  badge = 'Medalla Pokéball de Entrenamiento';
  rank = 'Aspirante en Práctica';
}

return [{
  json: {
    ...data,
    accuracy,
    badge,
    rank
  }
}];
